fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy_tree(root:&Path,dir:&Path,out:&Path){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();let n=e.file_name().to_string_lossy().to_string();let t=e.file_type().unwrap();if t.is_dir(){if n=="source"||n.starts_with("target-")||["profiles","frozen"].contains(&n.as_str()){continue}copy_tree(root,&p,out);}else if t.is_file()&&["rs","md","json","jsonl","log","txt","proof","public"].contains(&p.extension().and_then(|x|x.to_str()).unwrap_or("")){let dest=out.join(p.strip_prefix(root).unwrap());fs::create_dir_all(dest.parent().unwrap()).unwrap();fs::copy(p,dest).unwrap();}}}
fn inventory(root:&Path,dir:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){inventory(root,&p,out)}else{let rel=p.strip_prefix(root).unwrap().display().to_string();if rel!="SHA256SUMS"{out.insert(rel,hash(p));}}}}
